package it.frociart.app;
import java.util.*;import java.util.regex.*;import static it.frociart.app.FlowModel.*;
/** Safe, derived grouping of current graph edges. No hidden/persisted executable loop model. */
final class FlowCycle {
 static final class Info {int kind;String entry,check,increment,bodyEntry,exit,loopBranch,header;Set<String> members;FlowLoopBuilder.Spec spec;}
 static String next(Document d,String id,String branch){String result=null;int count=0;for(Edge e:d.edges)if(e.from.equals(id)&&e.branch.equals(branch)){result=e.to;count++;}return count==1?result:null;}
 static Set<String> body(Document d,String entry,String stop,String forbidden){Set<String> seen=new LinkedHashSet<>();ArrayDeque<String> q=new ArrayDeque<>();if(entry==null)return null;q.add(entry);while(!q.isEmpty()){String id=q.remove();if(id.equals(stop))continue;if(id.equals(forbidden))return null;if(!seen.add(id))continue;Node n=d.find(id);if(n==null||n.kind==START||n.kind==END)return null;String[] branches=n.kind==DECISION?new String[]{"true","false"}:new String[]{"next"};int count=0;for(Edge e:d.edges)if(e.from.equals(id))count++;if(count!=branches.length)return null;for(String b:branches){String to=next(d,id,b);if(to==null)return null;q.add(to);}}
  Set<String> returns=new HashSet<>();returns.add(stop);boolean changed;do{changed=false;for(Edge e:d.edges)if(seen.contains(e.from)&&returns.contains(e.to))changed|=returns.add(e.from);}while(changed);return returns.containsAll(seen)?seen:null;
 }
 static String negate(String value){value=value==null?"":value.trim();if(value.regionMatches(true,0,"non (",0,5)&&value.endsWith(")")){int depth=0;boolean outer=true,escaped=false;char quote=0;for(int i=4;i<value.length();i++){char c=value.charAt(i);if(quote!=0){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c==quote)quote=0;continue;}if(c=='"'||c=='\''){quote=c;continue;}if(value.charAt(i)=='(')depth++;else if(value.charAt(i)==')')depth--;if(depth==0&&i!=value.length()-1){outer=false;break;}}if(outer&&depth==0)return value.substring(5,value.length()-1).trim();}return "non ("+value+")";}
 static List<Info> find(Document graph){List<Info> result=new ArrayList<>();Set<String> forChecks=new HashSet<>();
  for(Node init:graph.nodes)if(init.kind==PROCESS){FlowPseudocode.ForPattern p=FlowPseudocode.inspectFor(graph,init);if(p==null)continue;Set<String> body=body(graph,p.body,p.increment.id,p.check.id);if(body==null)continue;Set<String> ids=new LinkedHashSet<>(body);ids.add(init.id);ids.add(p.check.id);ids.add(p.increment.id);boolean unsafe=false;for(Edge e:graph.edges)if(ids.contains(e.to)&&!ids.contains(e.from)&&!e.to.equals(init.id))unsafe=true;if(unsafe)continue;
   Info info=new Info();info.kind=0;info.entry=init.id;info.check=p.check.id;info.increment=p.increment.id;info.bodyEntry=p.body;info.exit=p.exit;info.loopBranch="true";info.members=ids;info.spec=FlowLoopBuilder.Spec.defaults(0);info.spec.variable=p.variable;info.spec.from=p.from;info.spec.to=p.to;info.spec.step=p.step;info.header=p.header;result.add(info);forChecks.add(p.check.id);
  }
  for(Node check:graph.nodes)if(check.kind==DECISION&&!forChecks.contains(check.id)){int count=0;for(Edge e:graph.edges)if(e.from.equals(check.id))count++;if(count!=2)continue;for(String branch:new String[]{"true","false"}){String entry=next(graph,check.id,branch),exit=next(graph,check.id,branch.equals("true")?"false":"true");if(entry==null||exit==null||entry.equals(exit)||exit.equals(check.id))continue;Set<String> body=body(graph,entry,check.id,exit);if(body==null)continue;boolean pre=false,external=false,unsafe=false;for(Edge e:graph.edges)if(e.to.equals(check.id)&&!e.from.equals(check.id)&&!body.contains(e.from))pre=true;
   for(Edge e:graph.edges)if(body.contains(e.to)&&!body.contains(e.from)&&!e.from.equals(check.id)){external=true;if(pre||!e.to.equals(entry))unsafe=true;}if(unsafe||!pre&&(body.isEmpty()||!external))continue;
   Info info=new Info();info.kind=pre?1:2;info.entry=pre?check.id:entry;info.check=check.id;info.bodyEntry=entry;info.exit=exit;info.loopBranch=branch;info.members=new LinkedHashSet<>(body);info.members.add(check.id);info.spec=FlowLoopBuilder.Spec.defaults(info.kind);info.spec.condition=branch.equals("true")?(check.text==null?"":check.text):negate(check.text);info.spec.initialize="";info.header=(pre?"MENTRE ":"RIPETI · continua mentre ")+info.spec.condition;result.add(info);break;
  }}
  result.sort(Comparator.<Info>comparingDouble(i->graph.find(i.entry).y).thenComparingInt(i->i.members.size()));return result;
 }
 static FlowLoopBuilder.Plan prepare(Document project,String functionId,Info info,FlowLoopBuilder.Spec spec){String before=FlowCodec.encode(project);Document candidate=project.copy(),graph=FlowFunctionEditing.graph(candidate,functionId);Info current=null;for(Info c:find(graph))if(c.entry.equals(info.entry)&&c.check.equals(info.check)&&c.kind==info.kind)current=c;if(current==null||spec.kind!=current.kind)throw new IllegalArgumentException("La struttura del ciclo è cambiata. Riapri il riepilogo; i singoli blocchi restano modificabili.");Function owner=FlowFunctionEditing.find(candidate,functionId);List<Node> changed=new ArrayList<>();Map<String,float[]> sizes=new HashMap<>();for(Node n:graph.nodes)sizes.put(n.id,new float[]{width(n),height(n)});
  if(current.kind==0){if(!java.util.Objects.equals(spec.variable,current.spec.variable))throw new IllegalArgumentException("Modifica il contatore nei singoli blocchi per aggiornare anche i suoi riferimenti.");FlowLoopBuilder.Spec tmp=FlowLoopBuilder.Spec.defaults(0);tmp.variable=spec.variable;tmp.from=spec.from;tmp.to=spec.to;tmp.step=spec.step;tmp.body="STAMPA 0";Set<String> names=new HashSet<>();Pattern identifiers=Pattern.compile(FlowEngine.IDENTIFIER_WORD_PATTERN);for(Document g:FlowLoopBuilder.graphs(candidate))for(Node n:g.nodes){Matcher m=identifiers.matcher(n.text==null?"":n.text);while(m.find())names.add(m.group().toLowerCase(Locale.ROOT));}if(owner!=null){for(Parameter p:owner.parameters)names.add(p.name);names.add(owner.returnVariable);}Document fragment=FlowPseudocode.decodeFragment(FlowLoopBuilder.source(tmp),candidate,owner,names);Info fresh=null;for(Info c:find(fragment))if(c.kind==0)fresh=c;Node oldInit=graph.find(current.entry),oldCheck=graph.find(current.check),oldIncrement=graph.find(current.increment),newInit=fragment.find(fresh.entry),newCheck=fragment.find(fresh.check),newIncrement=fragment.find(fresh.increment);List<String[]> a=FlowPseudocode.assignments(oldInit.text),b=FlowPseudocode.assignments(newInit.text);Map<String,String> rename=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);rename.put(b.get(1)[0],a.get(1)[0]);if(a.size()==3&&b.size()==3)rename.put(b.get(2)[0],a.get(2)[0]);oldInit.text=FlowFunctionEditing.rewrite(newInit.text,rename,false);oldCheck.text=FlowFunctionEditing.rewrite(newCheck.text,rename,false);oldIncrement.text=FlowFunctionEditing.rewrite(newIncrement.text,rename,false);if(a.size()==3&&b.size()==2){String stride=a.get(2)[0];oldInit.text+="; "+stride+" = int("+spec.step.trim()+", \"passo\")";oldCheck.text=FlowPseudocode.forCondition(spec.variable,a.get(1)[0],stride);oldIncrement.text=spec.variable+" = "+spec.variable+" + "+stride;}changed.addAll(Arrays.asList(oldInit,oldCheck,oldIncrement));
  }else{String condition=spec.condition==null?"":spec.condition.trim();if(condition.isEmpty()||condition.length()>8192||condition.chars().anyMatch(c->Character.isISOControl((char)c)))throw new IllegalArgumentException("Scrivi la condizione su una sola riga.");FlowEngine.checkExpression(condition,FlowFunctions.catalog(candidate));Node check=graph.find(current.check);check.text=current.loopBranch.equals("true")?condition:negate(condition);changed.add(check);}
  boolean resize=false;for(Node n:changed){FlowEngine.checkBlock(n,FlowFunctions.catalog(candidate),owner);float[] s=sizes.get(n.id);resize|=s[0]!=width(n)||s[1]!=height(n);}
  Set<String> backEdges=new HashSet<>();for(Info cycle:find(graph))for(Edge e:graph.edges){boolean back=cycle.kind==2?e.from.equals(cycle.check)&&e.to.equals(cycle.bodyEntry):e.to.equals(cycle.check)&&cycle.members.contains(e.from)&&!e.from.equals(cycle.entry);if(back)backEdges.add(e.id);}
  Set<String> upstream=new HashSet<>();ArrayDeque<String> rev=new ArrayDeque<>();for(Edge e:graph.edges)if(e.to.equals(current.entry)&&!current.members.contains(e.from)&&!backEdges.contains(e.id))rev.add(e.from);while(!rev.isEmpty()){String id=rev.remove();if(current.members.contains(id)||!upstream.add(id))continue;for(Edge e:graph.edges)if(e.to.equals(id)&&!backEdges.contains(e.id))rev.add(e.from);}Document local=new Document();for(Node n:graph.nodes)if(!upstream.contains(n.id))local.nodes.add(n);for(Edge e:graph.edges)if(!upstream.contains(e.from)&&!upstream.contains(e.to))local.edges.add(e);if(resize)FlowPlacement.grow(local,current.entry);FlowCodec.encode(candidate);
  FlowLoopBuilder.Plan plan=new FlowLoopBuilder.Plan();plan.project=candidate;plan.functionId=functionId;plan.entryId=current.entry;plan.baseDocument=before;plan.editing=true;Node entry=graph.find(current.entry);plan.origin=new float[]{entry.x,entry.y};return plan;
 }
}
